class BloomFilter:
    """
    A Bloom Filter implementation that utilizes a unique approach for hashing and bit array management.
    The design leverages a polynomial hash function to minimize collisions and ensures efficient membership
    testing while maintaining a specified false positive rate. The sizes and number of hash functions
    are calculated based on user inputs.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_functions(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate optimal bit array size using the formula based on the expected number of items and false positive rate."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions needed to minimize false positives."""
        return max(1, round(m / n * math.log(2)))

    def _polynomial_hash(self, item: str, seed: int) -> int:
        """Generate a hash value using a polynomial rolling hash function."""
        hash_value = 0
        for i, char in enumerate(item):
            hash_value += (ord(char) * (31 ** i)) + seed
        return hash_value % self.size

    def add(self, item: str) -> None:
